import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

export default function CreateEvent() {
  const [form, setForm] = useState({
    title: '',
    description: '',
    category: 'Technical',
    eventType: 'Physical',
    faculty: 'Computing',
    department: '',
    venue: '',
    date: '',
    endDate: '',
    capacity: '',
    organizerEmail: '',
    sponsorshipEnabled: false,
    budget: '',
    tags: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setForm({
      ...form,
      [name]: type === 'checkbox' ? checked : value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    if (!form.title || !form.date) {
      setError('Title and date are required');
      return;
    }

    setLoading(true);
    try {
      const body = {
        title: form.title,
        description: form.description,
        category: form.category,
        eventType: form.eventType,
        faculty: form.faculty,
        department: form.department,
        venue: form.venue,
        date: form.date,
        endDate: form.endDate,
        capacity: parseInt(form.capacity || '0', 10),
        organizer: 'Web UI',
        organizerEmail: form.organizerEmail,
        sponsorshipEnabled: form.sponsorshipEnabled,
        budget: parseFloat(form.budget || '0'),
        tags: form.tags ? form.tags.split(',').map(t => t.trim()) : []
      };

      const res = await fetch('http://localhost:5000/api/events', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });

      // if (!res.ok) {
      //   const data = await res.json();
      //   throw new Error(data.error || 'Failed to create event');
      // }
      if (!res.ok) {
  const text = await res.text();   // instead of res.json()
  console.log("Server error:", text);
  throw new Error(text || "Failed to create event");
}

      const created = await res.json();
      setLoading(false);
      navigate('/events');
    } catch (err) {
      setError(err.message);
      setLoading(false);
    }
  };

  return (
    <div className="container" style={{ padding: '40px 0' }}>
      <h2>Create Event</h2>
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label>Title</label>
          <input name="title" className="form-control" value={form.title} onChange={handleChange} required />
        </div>

        <div className="form-group">
          <label>Description</label>
          <textarea name="description" className="form-control" value={form.description} onChange={handleChange} />
        </div>

        <div className="form-row">
          <div className="form-group col-md-4">
            <label>Category</label>
            <select name="category" className="form-control" value={form.category} onChange={handleChange} required>
              <option>Technical</option>
              <option>Cultural</option>
              <option>Sports</option>
              <option>Workshop</option>
              <option>Seminar</option>
              <option>Competition</option>
              <option>Conference</option>
              <option>Other</option>
            </select>
          </div>
          <div className="form-group col-md-4">
            <label>Type</label>
            <select name="eventType" className="form-control" value={form.eventType} onChange={handleChange}>
              <option>Physical</option>
              <option>Virtual</option>
              <option>Hybrid</option>
            </select>
          </div>
          <div className="form-group col-md-4">
            <label>Faculty</label>
            <select name="faculty" className="form-control" value={form.faculty} onChange={handleChange} required>
              <option>Computing</option>
              <option>Engineering</option>
              <option>Business</option>
              <option>Architecture</option>
              <option>Hospitality</option>
              <option>Science</option>
              <option>Other</option>
            </select>
          </div>
        </div>

        <div className="form-row">
          <div className="form-group col-md-6">
            <label>Department</label>
            <input name="department" className="form-control" value={form.department} onChange={handleChange} />
          </div>
          <div className="form-group col-md-6">
            <label>Organizer Email</label>
            <input type="email" name="organizerEmail" className="form-control" value={form.organizerEmail} onChange={handleChange} />
          </div>
        </div>

        <div className="form-row">
          <div className="form-group col-md-6">
            <label>Date & Time</label>
            <input type="datetime-local" name="date" className="form-control" value={form.date} onChange={handleChange} required />
          </div>
          <div className="form-group col-md-6">
            <label>End Date & Time</label>
            <input type="datetime-local" name="endDate" className="form-control" value={form.endDate} onChange={handleChange} />
          </div>
        </div>

        <div className="form-group">
          <label>Venue</label>
          <input name="venue" className="form-control" value={form.venue} onChange={handleChange} />
        </div>

        <div className="form-group">
          <label>Capacity</label>
          <input type="number" name="capacity" className="form-control" value={form.capacity} onChange={handleChange} />
        </div>

        <div className="form-row">
          <div className="form-group col-md-4">
            <div className="form-check">
              <input
                type="checkbox"
                name="sponsorshipEnabled"
                className="form-check-input"
                checked={form.sponsorshipEnabled}
                onChange={handleChange}
              />
              <label className="form-check-label">Enable Sponsorship</label>
            </div>
          </div>
          <div className="form-group col-md-4">
            <label>Budget (LKR)</label>
            <input
              type="number"
              name="budget"
              className="form-control"
              value={form.budget}
              onChange={handleChange}
            />
          </div>
          <div className="form-group col-md-4">
            <label>Tags (comma-separated)</label>
            <input
              name="tags"
              className="form-control"
              value={form.tags}
              onChange={handleChange}
            />
          </div>
        </div>

        {error && <div style={{ color: 'red', marginTop: 8 }}>{error}</div>}

        <div style={{ marginTop: 12 }}>
          <button type="submit" className="green-button" disabled={loading}>{loading ? 'Creating...' : 'Create Event'}</button>
        </div>
      </form>
    </div>
  );
}
